// Framework data and pure helpers. framework.json is generated by scripts/extract_framework.py
import FW from "../data/framework.json";
export { FW };
export const JOB_LEVELS = ["6: Graduate","7: Junior","8: Mid","9: Senior","10: Lead","11: Principal","12: Head of"];
export const RATINGS = ["Partially Met","Met","Exceeding"];
export const POINTS = {"Partially Met":2,"Met":3,"Exceeding":4};
const defIdx = {}; Object.keys(FW.skills).forEach(k => defIdx[k.toLowerCase()] = FW.skills[k]);
export const skillDef = n => defIdx[(n||"").toLowerCase()] || {};
export const bullets = t => String(t||"").split(/\n+|•/).map(x=>x.replace(/^[\s\-–•]+/,"").trim()).filter(x=>x.length>3);
export const short = l => (l||"").split(": ")[1] || l;
export const isDef = v => v && !/^(not defined|none|n\/a)$/i.test(String(v).trim());
export const findRole = r => FW.roles.find(x => x.role.toLowerCase() === (r||"").toLowerCase());

/** Every skill and behaviour for the assessment's role and level, with the descriptors for now and the next level. */
export function getItems(A){
  const r = findRole(A.role), i = FW.levels.indexOf(A.level);
  const nextJob = JOB_LEVELS[JOB_LEVELS.indexOf(A.level)+1] || null;
  const sk = r.skills.filter(s => isDef(s.levels[i])).map(s => {
    const next = isDef(s.levels[i+1]) ? s.levels[i+1] : null;
    return {key:"s:"+s.skill, kind:"Skill", name:s.skill, required:s.levels[i], next, nextJob,
      now: bullets(skillDef(s.skill)[s.levels[i]]), nextText: next && next!==s.levels[i] ? bullets(skillDef(s.skill)[next]) : []};
  });
  const bh = FW.behaviours.map(b => ({key:"b:"+b.name, kind:"Behaviour", name:b.name, required:A.level, nextJob,
      now: bullets(b.levels[A.level]), nextText: nextJob ? bullets(b.levels[nextJob]) : []}));
  return sk.concat(bh);
}
